INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Product Backlog immer statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Wird fortlaufend angepasst"}, {"text": "Ja", "correct": false, "because": "Dynamisch durch Feedback"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Product Backlogs?', 3, '[{"text": "Priorisierung von Aufgaben", "correct": true, "because": "Fokussiert Team auf Wert"}, {"text": "Dokumentation aller Ideen", "correct": false, "because": "Nur priorisierte Aufgaben"}, {"text": "Manuelle Planung", "correct": false, "because": "Automatisierte Tools üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise in ein Product Backlog?', 5, '[{"text": "User Stories", "correct": true, "because": "Beschreiben Nutzeranforderungen"}, {"text": "Fehlerbehebungen", "correct": true, "because": "Verbessern Produktqualität"}, {"text": "Marketingpläne", "correct": false, "because": "Nicht entwicklungsspezifisch"}, {"text": "Hardwarewartung", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Product Owner priorisiert das Backlog. b) Es enthält nur technische Aufgaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) enthält auch Nutzeraufgaben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verwaltung eines Product Backlogs?', 4, '[{"text": "Priorisierungskriterien", "correct": false, "because": "Bestimmen Reihenfolge"}, {"text": "Stakeholder-Feedback", "correct": false, "because": "Beeinflusst Inhalte"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Backlog"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Product Backlog nur vom Product Owner verwaltet wird?', 2, '[{"text": "Nein", "correct": true, "because": "Team trägt bei"}, {"text": "Ja", "correct": false, "because": "Kollaborative Pflege"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode verbessert die Backlog-Pflege?', 3, '[{"text": "Backlog Refinement", "correct": true, "because": "Verfeinert und priorisiert"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Ineffizient"}, {"text": "Manuelle Sortierung", "correct": false, "because": "Strukturierte Methoden besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Product Backlog?', 5, '[{"text": "Transparenz", "correct": true, "because": "Zeigt Prioritäten"}, {"text": "Fokus auf Wert", "correct": true, "because": "Höchste Priorität zuerst"}, {"text": "Statische Planung", "correct": false, "because": "Dynamisch angepasst"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Kontinuierlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Backlog enthält User Stories. b) Es ist nur für Entwickler relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) betrifft alle Stakeholder"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Product Backlog?', 4, '[{"text": "Priorisierung", "correct": false, "because": "Kern des Backlogs"}, {"text": "User Stories", "correct": false, "because": "Typische Inhalte"}, {"text": "Grafische Animationen", "correct": true, "because": "Kein Backlog-Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Product Backlog dasselbe wie ein Sprint Backlog?', 2, '[{"text": "Nein", "correct": true, "because": "Sprint Backlog ist Teilmenge"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien beeinflussen die Priorisierung?', 4, '[{"text": "Geschäftswert", "correct": true, "because": "Maximiert Nutzen"}, {"text": "Risiko", "correct": true, "because": "Beeinflusst Dringlichkeit"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Product Backlog nur technische Aufgaben enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Enthält auch User Stories"}, {"text": "Ja", "correct": false, "because": "Vielfältige Inhalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Backlog-Verwaltung?', 3, '[{"text": "Nutzerwert", "correct": true, "because": "Fokussiert auf Kundenbedarf"}, {"text": "Minimale Details", "correct": false, "because": "Klarheit wichtig"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Strukturierte Prozesse besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Backlog Refinement klärt Details. b) Das Backlog ist statisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist dynamisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die Backlog-Verwaltung?', 5, '[{"text": "Jira", "correct": true, "because": "Bietet Priorisierung"}, {"text": "Trello", "correct": true, "because": "Visualisiert Aufgaben"}, {"text": "Texteditor", "correct": false, "because": "Kein Backlog-Tool"}, {"text": "Bildbearbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Product Backlog unwichtig?', 3, '[{"text": "Priorisierung", "correct": false, "because": "Bestimmt Fokus"}, {"text": "Transparenz", "correct": false, "because": "Fördert Verständnis"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Backlog-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Product Backlog für mehrere Teams genutzt werden kann?', 2, '[{"text": "Ja", "correct": true, "because": "Einheitliches Backlog möglich"}, {"text": "Nein", "correct": false, "because": "Koordination machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Enthält das Backlog immer nur kurzfristige Aufgaben?', 3, '[{"text": "Nein", "correct": true, "because": "Langfristige Items möglich"}, {"text": "Ja", "correct": false, "because": "Mix aus kurz- und langfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Product Backlog?', 4, '[{"text": "Planung eines Software-Features", "correct": true, "because": "Typische Backlog-Aufgabe"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Kreative Aufgabe"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
